import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.DGzMGr_a.js";const g=JSON.parse('{"title":"启燃测试倒计时一周，这份准备清单请收好","description":"RO3 启燃测试 6月25日开服，从注册到下载到职业选择，把该准备的都理一遍，免得开测手忙脚乱。","frontmatter":{"title":"启燃测试倒计时一周，这份准备清单请收好","date":"2026-06-17T00:00:00.000Z","description":"RO3 启燃测试 6月25日开服，从注册到下载到职业选择，把该准备的都理一遍，免得开测手忙脚乱。"},"headers":[],"relativePath":"news/ignition-test-prep.md","filePath":"news/ignition-test-prep.md","lastUpdated":1782133791000}'),n={name:"news/ignition-test-prep.md"};function i(s,t,p,l,d,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="启燃测试倒计时一周-这份准备清单请收好" tabindex="-1">启燃测试倒计时一周，这份准备清单请收好 <a class="header-anchor" href="#启燃测试倒计时一周-这份准备清单请收好" aria-label="Permalink to &quot;启燃测试倒计时一周，这份准备清单请收好&quot;">​</a></h1><blockquote><p>2026-06-17</p></blockquote><p>距离6月25日启燃测试开服还有一周，招募到6月23日截止。还没报名的抓紧，报了的可以看看要准备什么。</p><h2 id="报名了没" tabindex="-1">报名了没 <a class="header-anchor" href="#报名了没" aria-label="Permalink to &quot;报名了没&quot;">​</a></h2><p>这次测试是审核制，不是报了就能进。去官网 ro3global.com 预约就行，填个问卷。招募到6月23日下午6点截止，官网会通知中选的人。</p><p>如果没被选上也不用太灰心，这次主要是技术验证，后面正式上线前应该还有机会。</p><h2 id="这次测什么" tabindex="-1">这次测什么 <a class="header-anchor" href="#这次测什么" aria-label="Permalink to &quot;这次测什么&quot;">​</a></h2><p>根据官方公告和巴哈姆特的报道，启燃测试会开放这些内容：</p><p><strong>PC自定义界面</strong>。这是最大的看点。之前先锋测试被吐槽最多的就是PC版UI完全是手机那一套，点起来很别扭。这次加入了自由调整界面布局的功能，按钮位置、大小、快捷键应该都能自己设了。具体的自由度有多高，得实际上手才知道。</p><p><strong>五人MVP副本</strong>。RO的老玩家都知道，以前MVP都是野外刷新，一群人蹲点抢。这次改成副本制了，每个MVP有专属的机制和打法，不用再跟人抢怪了。对休闲玩家来说是个好消息。</p><p><strong>十人副本</strong>。有普通和困难两种难度，官方强调以&quot;互动&quot;为核心设计理念。按照之前GNN报道的说法，boss机制融合了环境互动和职业配合，不是那种站桩输出的本。</p><p><strong>核心养成系统</strong>。天赋、装备、卡片都会开放。注意测试只有一周时间，不太可能体验完整养成线，但至少可以摸到各个系统的雏形和手感。</p><h2 id="职业选什么" tabindex="-1">职业选什么 <a class="header-anchor" href="#职业选什么" aria-label="Permalink to &quot;职业选什么&quot;">​</a></h2><p>测试的目的是体验游戏，不是冲进度。建议选自己真正想玩的职业，一周时间足够体验职业特色和基础玩法了。</p><p>如果实在不知道选什么：</p><ul><li>想简单粗暴就剑士，能抗能打，操作门槛最低</li><li>想打伤害就法师，AOE清怪效率高</li><li>想挑战操作就刺客，背刺走位都有讲究</li><li>想组队不愁就牧师，玩的人少需求大</li></ul><h2 id="几点提醒" tabindex="-1">几点提醒 <a class="header-anchor" href="#几点提醒" aria-label="Permalink to &quot;几点提醒&quot;">​</a></h2><p><strong>删档测试</strong>。测试结束后数据会清空，别太在意练级速度，重点体验玩法本身。</p><p><strong>多平台互通</strong>。PC和手机数据互通，可以在电脑上打副本、手机上做日常。建议两边都装一下，体验跨平台到底做得怎么样，这也是RO3的核心卖点之一。</p><p><strong>反馈渠道</strong>。这次测试的目的就是为了收集反馈和做压力测试。如果遇到bug或者有建议，通过官方Discord反馈是最直接的。官方说他们会看每一条反馈。</p><p><strong>时间只有一周</strong>。6月25日到7月2日，整整7天。内容会分阶段开放，不是一开服全部解锁。合理安排时间，想体验的内容优先玩。</p><h2 id="最后说两句" tabindex="-1">最后说两句 <a class="header-anchor" href="#最后说两句" aria-label="Permalink to &quot;最后说两句&quot;">​</a></h2><p>从去年8月先锋测试到现在，过了大半年，RO3终于又要开测了。这段时间官方做了不少调整，PC界面重做、副本机制完善、共创议事录也出了两期。这次测试基本能看出游戏最终上线时的样子了。</p><p>不管结果如何，能亲手摸到游戏总是好事。祝各位都能抽到资格。</p><p>有新的消息我会继续更新。</p>',25)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
